</template>
<script setup lang="ts">
import ItemMenu from '@/components/Global/ItemMenu.vue';
import UserPanel from '@/components/Global/UserPanel.vue';
import { useApi } from '@/composables/api';
import { useDashboardGoalsStore } from '@/store/dashboardGoals';
import { ProjectGoal } from '@/interface/projectInterface';
import { useAuthUserStore } from '@/store/auth';
import { DateTime } from 'luxon';
import { computed } from 'vue';
import { useRoute } from 'vue-router';
import GoalStatus from './GoalStatus.vue';
import IssueStatus from './SalaryIssue/IssueStatus.vue';

const props = defineProps<{
    item: ProjectGoal;
    projectId?: number;
}>();

const emit = defineEmits<{
    editGoal: [goal: ProjectGoal];
}>();
const route = useRoute()

const auth = useAuthUserStore()

const { overallScore, getGoals, invalidateCache } = useDashboardGoalsStore()

const isOverdue = computed(() => {
    const now = DateTime.now()
    const endDate = DateTime.fromISO(props.item.end_date)
    return now > endDate && props.item.status < 9
})

const isManager = computed(() => {
    return props.item.project?.is_manager
})

const isMember = computed(() => {
    return props.item.project?.is_member
})

const editable = computed(() => {
    return (props.item.status < 2) && (auth.activeUser.id === props.item.user_id || isManager.value || isMember.value || auth.isAdmin)
})

const api = useApi()

const deleteGoal = async (goal: ProjectGoal) => {


    await api.del(`/delete_project_goal`, {
        id: goal.id,
    }, {
        ask: '成果目標を削除しますか？\n削除すると、昇給課題も一緒に削除されます。',
        toast: '成果目標を削除しました。'
    })
    invalidateCache()
    getGoals(props.item.user_id, props.item.year, props.item.which_half)

}

const applyEdit = async (goal: ProjectGoal) => {

    await api.put('/approve_outcome_goal', {id: goal.id, status: 4}, {
        toast: '変更申請しました。',
        ask: 'この成果目標の変更を申請しますか？'
    })
    invalidateCache()
    getGoals(props.item.user_id, props.item.year, props.item.which_half)
}

</script>